n = int(input())
for i in range(n):
    a = int(input())
    b = int(input())
    c = int(input())
    d = int(input())
    if b < 0:
        a, b = -a, -b
    if d < 0:
        c, d = -c, -d
    left = a * d
    right = b * c
    print(f"{a} * {d} = {left}, {b} * {c} = {right}")
    if left < right:
        print(f"{a}/{b} < {c}/{d}")
    elif left > right:
        print(f"{a}/{b} > {c}/{d}")
    else:
        print(f"{a}/{b} = {c}/{d}")
